import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {jinsedragonSession,jinsedragonPayload} from './sg-jinsedragon-source.mjs';
import {jinsedragonCodec} from './sg-jinsedragon-codec.mjs';
import {bootstrap,review,settled,request} from './sg-jinsedragon-base.mjs';
import {analyzer} from '../analyzer.mjs';
import {createProtocolSessions} from './sg-protocol-session.mjs';
import {createTaskRuntime} from './sg-task-runtime.mjs';
const plan=JSON.parse(fs.readFileSync('config/ag-rolling-plans.json')).plans['32779'];
const init=(session='rotated',balance=1000)=>`<GameResponse type="Init"><Header gameID="20401" versionID="1_0" isRecovering="N" sessionID="${session}"/><AccountData><AccountData/></AccountData><Balances><Balance name="CASH_BALANCE" value="${balance}"/></Balances><GameInfo><Stakes>100|200|</Stakes><PageInfo pageCount="1"/></GameInfo></GameResponse>`;
const step=(msg,payload,text)=>({msgId:msg,requestPayload:payload,responsePayload:text,responseXml:text,responseBalance:Number(text.match(/name="CASH_BALANCE" value="(\d+)"/)[1]),elapsedMs:0});
const base={mode:'demo',sessionId:'Free:offline-only',operatorId:'offline'};
const ctx={base,plan,queueId:'offline',kind:'canary',index:1,owner:'offline-owner',ordinal:1,guard:async()=>{}};
const logic=(session='paid',cash=1120,game="<GameResult stake=\"100\" stakePerLine=\"100\" paylineCount=\"1\" totalWin=\"220\" betID=\"\"><ReelResults numSpins=\"1\"><ReelSpin spinIndex=\"0\" reelsetIndex=\"0\" anywayWins=\"1\" scatterWinCount=\"0\" totalSpinWin=\"20\" freeSpin=\"N\" bonusAwarded=\"N\"><ReelStops>1|2|3|4|5</ReelStops><AnywayWin winIndex=\"0\" winVal=\"20\" ways=\"1\" awardIndex=\"0\">25|26</AnywayWin></ReelSpin></ReelResults><BGInfo totalWagerWin=\"220\" bgWinnings=\"220\" baseGameSpinsRemaining=\"0\" isMaxWin=\"0\" expReelTriggerType=\"2\" reelHeights=\"4\"/><Orbs numJackpotWins=\"0\"><Orb awardIndex=\"10\" amount=\"400\" position=\"0\" winning=\"n\" isJackpot=\"n\"/><Orb awardIndex=\"12\" amount=\"200\" position=\"1\" winning=\"y\" isJackpot=\"n\"/><Orb awardIndex=\"11\" amount=\"300\" position=\"2\" winning=\"n\" isJackpot=\"n\"/><Orb awardIndex=\"9\" amount=\"500\" position=\"3\" winning=\"n\" isJackpot=\"n\"/><Orb awardIndex=\"12\" amount=\"200\" position=\"4\" winning=\"n\" isJackpot=\"n\"/><Orb awardIndex=\"8\" amount=\"600\" position=\"5\" winning=\"n\" isJackpot=\"n\"/><Orb awardIndex=\"8\" amount=\"600\" position=\"6\" winning=\"n\" isJackpot=\"n\"/><Orb awardIndex=\"8\" amount=\"600\" position=\"7\" winning=\"n\" isJackpot=\"n\"/><Orb awardIndex=\"7\" amount=\"800\" position=\"8\" winning=\"n\" isJackpot=\"n\"/></Orbs></GameResult>")=>`<GameResponse type="Logic"><Header gameID="20401" versionID="1_0" isRecovering="N" readyForEndGame="Y" sessionID="${session}"/><AccountData><AccountData><CurrencyMultiplier>1</CurrencyMultiplier></AccountData></AccountData><Balances><Balance name="CASH_BALANCE" value="${cash}"/></Balances>${game}</GameResponse>`;
const end=(session='end',cash=1120)=>`<GameResponse type="EndGame"><Header gameID="20401" versionID="1_0" isRecovering="N" readyForEndGame="N" sessionID="${session}"/><AccountData/><Balances><Balance name="CASH_BALANCE" value="${cash}"/></Balances></GameResponse>`;
const raw=()=>({fixtureOnly:false,protocol:'wms',sourceKey:plan.sourceKey,roundFieldsVersion:'sg-round-fields-v1',startBalanceRaw:1000,
 steps:[step('Logic',jinsedragonPayload({MSGID:'Logic'},'first',true),logic()),step('EndGame',jinsedragonPayload({MSGID:'EndGame'},'paid'),end())]});
test('Jinse Dao Dragon transport has distinct anonymous owners, fixed catalog/WMS IDs and BET guard for the sole paid Logic for 100/Stake.total',async()=>{
 let calls=0;const guards=[];const s=jinsedragonSession({...ctx,guard:async v=>guards.push(v),fetchSource:async()=>{
  calls++;return {ok:true,status:200,headers:{getSetCookie:()=>[]},text:async()=>init()};}});
 const other=jinsedragonSession({...ctx,ordinal:2,fetchSource:async()=>{throw Error('unused');}});
 assert.equal(calls,0);assert.notEqual(s.identity,other.identity);assert.notEqual(s.session,other.session);
 assert.throws(()=>jinsedragonSession({...ctx,plan:{...plan,runtimeGameId:20401},fetchSource:async()=>{}}),/SOURCE_SCOPE/);
 await s.send(jinsedragonPayload({MSGID:'Logic'},s.session,true),'Logic');assert.equal(calls,1);assert.equal(guards[0].msgId,'BET');s.close();other.close();
});
test('Jinse Dao Dragon actual Python IPC independently validates Init, ordinary routing, own AnywayWin and winning Orb money and full record',async()=>{
 const parser=analyzer(),s={session:'first',setSession(v){this.session=v;}};const codec=await jinsedragonCodec({plan,session:s,sequence:()=>1,worker:20,batchId:21,createAnalyzer:()=>parser});
 try{
  assert.equal(await codec.bootstrap(async(msg,payload)=>step(msg,payload,init('first'))),1000);
  const r=codec.createRaw({balance:1000}),a=await codec.next(r);assert.equal(a.MSGID,'Logic');assert.equal(codec.guardMsg(a.MSGID,codec.payload(a)),'BET');
  r.steps.push(step(a.MSGID,codec.payload(a),logic()));const b=await codec.next(r);assert.equal(b.MSGID,'EndGame');assert.equal(s.session,'paid');
  r.steps.push(step(b.MSGID,codec.payload(b),end()));assert.equal(await codec.next(r),null);
  const p=await codec.prepare(r,{attempt:'offline',sessionHash:'a'.repeat(64)});assert.equal(p.record.mul,220/100);assert.equal(p.record.bonus,0);assert.equal(p.endBalanceRaw,1120);assert(p.independentlyVerified);
  const bad=structuredClone(p.record);bad.raw.steps[1].responseBalance++;
  await assert.rejects(()=>parser.call({op:'verify',plan,raw:bad.raw,record:bad}),/BALANCE/);
 }finally{codec.close();parser.close();}
});
test('Jinse Dao Dragon rejects unknown awards, Payline, own BG/Orbs joint and feature states, wrong wager/money and mismatched session before EndGame',()=>{
 for(const [from,to] of [["freeSpin=\"N\"", "freeSpin=\"Y\""], ["bonusAwarded=\"N\"", "bonusAwarded=\"Y\""], ["anywayWins=\"1\"", "anywayWins=\"2\""], ["scatterWinCount=\"0\"", "scatterWinCount=\"1\""], ["stake=\"100\"", "stake=\"101\""], ["stakePerLine=\"100\"", "stakePerLine=\"101\""], ["paylineCount=\"1\"", "paylineCount=\"2\""], ["isMaxWin=\"0\"", "isMaxWin=\"1\""], ["baseGameSpinsRemaining=\"0\"", "baseGameSpinsRemaining=\"1\""], ["winVal=\"20\"", "winVal=\"21\""], ["awardIndex=\"0\"", "awardIndex=\"99999\""], ["ways=\"1\"", "ways=\"99999\""], ["winIndex=\"0\"", "winIndex=\"1\""], [">25|26</AnywayWin>", ">0|1|40</AnywayWin>"], ["totalSpinWin=\"20\"", "totalSpinWin=\"21\""], ["totalWin=\"220\"", "totalWin=\"221\""], ["<BGInfo", "<UnknownFeature/><BGInfo"], ["</GameResult>", "<WheelInfo featureType=\"FreeSpins\" wheelStop=\"2\"/></GameResult>"], ["reelsetIndex=\"0\"", "reelsetIndex=\"1\""], ["spinIndex=\"0\"", "spinIndex=\"1\""], ["<CurrencyMultiplier>1</CurrencyMultiplier>", "<CurrencyMultiplier>2</CurrencyMultiplier>"], ["readyForEndGame=\"Y\"", "readyForEndGame=\"N\""], ["<BGInfo", "unexpected<BGInfo"], ["expReelTriggerType=\"2\"", "expReelTriggerType=\"99\""], ["reelHeights=\"4\"", "reelHeights=\"99\""], ["numJackpotWins=\"0\"", "numJackpotWins=\"1\""], ["winning=\"y\"", "winning=\"n\""], ["position=\"0\"", "position=\"99\""], ["<BGInfo", "<BGInfo isBigBet=\"0\""]]){
  const r=raw();assert(r.steps[0].responsePayload.includes(from));r.steps[0].responsePayload=r.steps[0].responsePayload.replace(from,to);r.steps[0].responseXml=r.steps[0].responsePayload;assert.throws(()=>review(r));
 }
 const r=raw();r.steps[1].requestPayload=r.steps[1].requestPayload.replace('sessionID="paid"','sessionID="wrong"');assert.throws(()=>review(r),/SESSION/);
});
test('Jinse Dao Dragon requires its own EndGame acknowledgement and rejects early, missing or changed-cash confirmation',()=>{
 const r=raw();assert.throws(()=>settled({...r,steps:r.steps.slice(0,1)},'a'.repeat(64)),/INCOMPLETE/);
 assert.throws(()=>review({...r,steps:[r.steps[1]]}),/SEQUENCE/);assert.throws(()=>review({...r,steps:[...r.steps,r.steps[1]]}),/SEQUENCE/);

 const content=structuredClone(r);content.steps[1].responsePayload=content.steps[1].responseXml=content.steps[1].responseXml.replace('<AccountData/>','<AccountData><CurrencyMultiplier>1</CurrencyMultiplier></AccountData>');assert.throws(()=>review(content),/ENDGAME_MISMATCH/);
 const bad=structuredClone(r);bad.steps[1]=step('EndGame',bad.steps[1].requestPayload,end('end',1121));assert.throws(()=>review(bad),/BALANCE/);
});
test('Jinse Dao Dragon bootstrap capability is restricted and cannot grant recovery, result, missing stake or unknown Init nodes',async()=>{
 const payload=jinsedragonPayload({MSGID:'Init'},'first'),parser=analyzer();
 try{for(const text of [init().replace('100|200|','99|200|'),init().replace('isRecovering="N"','isRecovering="Y"'),
  init().replace('</GameResponse>','<GameResult/></GameResponse>'),init().replace('</GameResponse>','<Unknown/></GameResponse>'),init().replace('pageCount="1"','pageCount="2"')]){
  const d=step('Init',payload,text);assert.throws(()=>bootstrap(d,'first'));await assert.rejects(()=>parser.call({op:'jinsedragon_bootstrap',plan,step:d,session:'first'}));
 }}finally{parser.close();}
});
test('Jinse Dao Dragon unknown transport issues one Init and retains its unresolved durable intent with no retry or BET',async()=>{
 let calls=0,intents=0,responses=0,closed;
 const protocol=createProtocolSessions({game:{gameId:'32779'},queueId:'offline',kind:'canary',index:1,owner:'offline-owner',plan,guard:async()=>{},
  spoolFactory:()=>({append(){},confirmed(){},close(){}}),journal:{open:async()=>{},intent:async()=>{intents++;return {durable:true};},response:async()=>{responses++;return {durable:true};},close:async v=>{closed=v;},auditSources:async()=>{}},
  createSession:c=>jinsedragonSession({...ctx,...c,fetchSource:async()=>{calls++;throw Error('unknown');}}),
  createCodec:(_p,s)=>jinsedragonCodec({plan,session:s,sequence:()=>1,worker:20,batchId:21})});
 const s=await protocol.open();await assert.rejects(()=>s.captureRound({}),/SOURCE_NETWORK_OUTCOME_UNKNOWN/);await s.close();assert.equal(calls,1);assert.equal(intents,1);assert.equal(responses,0);assert.equal(closed.awaiting,1);assert.equal(closed.unknownRequests,1);assert.equal(closed.ready,false);
});
test('Task factory selects Jinse Dao Dragon without a supplied transport and final proof requires immutable full wiring evidence',async()=>{
 const runtime=createTaskRuntime({store:{},transport:{},game:{gameId:'32779',baseline:0},queueId:'offline',kind:'canary',index:1,quota:10,owner:'offline-owner',plan,base,guard:async()=>{}});
 await assert.rejects(()=>runtime.protocol.open(),/SG_GITHUB_SOURCE_REQUIRED/);await runtime.close();
 const parser=analyzer();try{
  const changed={...plan,wmsGameId:20442};await assert.rejects(()=>parser.call({op:'plan',plan:changed}),/ROLLING_PLAN_CHANGED/);
 }finally{parser.close();}
});

